font-size:18px;"> Waterproof Canvas</span></span><br/> <span style=''color:#59595B;font-family:"font-size:22px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Canvas</span></span><br/> <span style=''color:#59595B;font-family:"font-size:22px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">3)Rolls Solvent Materials:</span></span><br/> <span style=''color:#59595B;font-family:"font-size:22px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Solvent PP Film</span></span><br/> <span style=''color:#59595B;font-family:"font-size:22px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;"> One Way Vision</span></span><br/> <span style=''color:#59595B;font-family:"font-size:22px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Self Adhesive Vinyl</span></span><br/> <span style=''color:#59595B;font-family:"font-size:22px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Solvent Photo Paper</span></span><br/> <span style=''color:#59595B;font-family:"font-size:22px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">4)Lamination Films:</span></span><br/> <span style=''color:#59595B;font-family:"font-size:22px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Glossy Lamination Film 70 80</span></span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> Matte Lamination Film 70 80 110</sp