INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (64, 276, 'LOWER WEIGHT COATED PAPER', '../upload/image/20181227/20181227121111_41698.jpg', '<p></p><p align="center" style="color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="background:white;color:black;font-size:13.5pt;"><span style=''font-family:"font-size:22px;''><span style="background:white;color:black;font-size:13.5pt;"><span style="font-size:24px;"><strong><span style="font-size:24px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">LOWER WEIGHT COATED PAPER</span><br/> <br/> </span></strong></span></span></span></span></p> <p class="" style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">LWC, called Light Weight Coated Paper. It refers to a class of low weight coated paper processing, generally in the 40-90g/m2. This kind of paper front and back are coated with a layer of thin coating (composed of calcium carbonate and cationic starch), and then through a super calendar so as to improve its physical properties and printability. The chemical composition of this paper, the long fiber bleached softwood chemical pulp 40%; mechanical wood pulp accounted for 60%. </span></span></p> <h6 class="" style="text-align:left;color:#59595B;text-indent:0px;font-family:宋体;font-style:normal;background-color:#FFFFFF;"> <span style="font-size:20px;"><span style="font-size:20px;"><br/> </span><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">The performance of paper</span></span></span> </h6> <p class="" style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-size:20px;"><span style="font-size:20px;"><span style="font-size:24px;"><br/> </span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1. This kind of paper between the performance of coated paper and offset paper, the effect of its color printing comparable to coated paper, and its opacity, smoothness, gloss and printability is good. </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">2. This kind of paper and low cost. It costs between the coated paper and offset paper between. However, the printing quality can be achieved comparable with the effect of coated paper, so a high value-added paper.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">3. However, the durability of this paper is small, so the long-term retention of printed materials is not easy. </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Usage:</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">This paper is mainly used for printing magazines, catalogs, advertising, trademarks, newspaper inserts and so on</span>.<br/> </span></span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (64, 274, 'Copy paper in jumbo roll size', '../upload/image/20181227/20181227113024_63541.jpg', '<p></p><p><span style="color:#009900;font-family:Tahoma;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"><strong>Copy paper in jumbo rolls size</strong></span></p> <p><span style="color:#009900;font-size:18px;background-color:#FFFFFF;font-family:Tahoma;">We are one of the fewer factories who can offer only Copy paper jumbo roll products with GRM is from 48 GRM to 100GRM with outstanding quality . We import the raw mateiral(wooden pulp) from overseas like Russia and other area .Also we are one of the fewer factories who can offer only LWC paper products in quality actual 100% wooden pulp .</span></p> <p><span style="color:#009900;font-size:18px;background-color:#FFFFFF;font-family:Tahoma;">Roll size:</span></p> <p><span style="color:#E53333;font-size:18px;background-color:#FFFFFF;"><span style="font-family:Tahoma;font-size:18px;color:#009900;">Photocopy PAPER JUMBO ROLLS on a reel to be sheeted into A4 &amp; A3 ream sizes.</span></span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-size:22px;"><span style=''font-family:"font-size:22px;''> <span style="color:#009900;font-family:Tahoma;font-size:18px;">Basis weight range: 70-75- 80 g/m2</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">The paper reel will be used on the following machine:</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">Core: 76MM (3"), 152.4mm (6")</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">Coil Max: 600mm -1,200mm</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">Max Weight: 2000Kgs</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">Max Width: 1500mm (For example: 840 1055MM...） </span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">------ Two types following :</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">Economy type:</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- grammage: (80 +- 3) g/sm</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- caliper: (106 +- 4) mm/1000</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- stiffness L&amp;W:</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;"> MD min 100 mN</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;"> CD min 40 mN</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- roughness bendtsen: (200 +- 50) ml/min</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- CIE whiteness: 146 +- 3</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- brightness with UV: (103,5 +- 1,5) %</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- opacity: min 90 %.</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">Allround type:</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- grammage: (80 +- 3) g/sm</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- caliper: (106 +- 3) mm/1000</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- stiffness L&amp;W:</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;"> MD min (125 +- 15) mN</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;"> CD min (60 +- 10) mN</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- roughness bendtsen: (200 +- 50) ml/min</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- CIE whiteness: 160 +- 3</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">- brightness with UV: (110 +- 1,5) %</span><br/> </span><span style="color:#009900;font-family:Tahoma;font-size:18px;">- opacity: min 91 %.</span></span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <img alt="" src="../upload/image/20180826/20180826220101_80230.jpg"/><img alt="" src="../upload/image/20180826/20180826220101_37191.jpg"/><img alt="" src="../upload/image/20180826/20180826220101_63871.jpg"/><img alt="" src="../upload/image/20180826/20180826220101_71712.jpg"/><img alt="" src="../upload/image/20180826/20180826220101_37800.jpg"/><img alt="" src="../upload/image/20180826/20180826220102_85923.jpg"/><img alt="" src="../upload/image/20180826/20180826220102_41720.jpg"/><img alt="" src="../upload/image/20180826/20180826220102_10909.jpg"/><img alt="" src="../upload/image/20180826/20180826220102_47408.jpg"/><img alt="" src="../upload/image/20180826/20180826220102_79296.jpg"/><img alt="" src="../upload/image/20180826/20180826220103_43708.jpg"/><img alt="" src="../upload/image/20180826/20180826220103_92534.jpg"/></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (64, 273, 'COPY PAPER OEM PRODUCTS', '../upload/image/20181227/20181227113041_70990.jpg', '<p></p><p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''font-family:"font-size:22px;''>COPY PAPER OEM PRODUCTS</span></p> <span style=''color:#59595B;font-family:"font-size:22px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <p style="text-indent:20pt;"> <img border="0" src="../upload/image/no-photo.png"/></p> <p style="text-indent:20pt;"> <img border="0" src="../upload/image/no-photo.png"/></p> <p style="text-indent:20pt;"> <img border="0" src="../upload/image/no-photo.png"/></p> <p style="text-indent:20pt;"> <img border="0" src="../upload/image/no-photo.png"/><br/> <br/> <br/> <img border="0" src="../upload/image/no-photo.png"/></p> <p style="text-indent:20pt;"> <img border="0" src="../upload/image/no-photo.png"/></p> <p style="text-indent:20pt;"> <img alt="" src="../upload/image/20180826/20180826215338_99101.jpg"/><img alt="" src="../upload/image/20180826/20180826215338_88060.jpg"/><img alt="" src="../upload/image/20180826/20180826215338_47905.jpg"/><img alt="" src="../upload/image/20180826/20180826215338_87406.jpg"/><img alt="" src="../upload/image/20180826/20180826215339_79205.jpg"/><img alt="" src="../upload/image/20180826/20180826215339_35636.jpg"/><img alt="" src="../upload/image/20180826/20180826215340_77615.jpg"/><img alt="" src="../upload/image/20180826/20180826215340_62608.jpg"/><img alt="" src="../upload/image/20180826/20180826215340_15625.jpg"/><img alt="" src="../upload/image/20180826/20180826215340_25249.jpg"/><img alt="" src="../upload/image/20180826/20180826215340_37347.jpg"/><img alt="" src="../upload/image/20180826/20180826215341_82193.jpg"/><img alt="" src="../upload/image/20180826/20180826215341_37106.jpg"/><img alt="" src="../upload/image/20180826/20180826215355_30349.jpg"/><img alt="" src="../upload/image/20180826/20180826215355_52651.jpg"/><img alt="" src="../upload/image/20180826/20180826215355_36740.jpg"/><img alt="" src="../upload/image/20180826/20180826215356_75220.jpg"/><img alt="" src="../upload/image/20180826/20180826215356_51308.jpg"/><img alt="" src="../upload/image/20180826/20180826215356_62174.jpg"/><img alt="" src="../upload/image/20180826/20180826215356_66065.jpg"/><img alt="" src="../upload/image/20180826/20180826215356_68279.jpg"/><img alt="" src="../upload/image/20180826/20180826215356_54906.jpg"/><img alt="" src="../upload/image/20180826/20180826215357_55406.jpg"/><img alt="" src="../upload/image/20180826/20180826215357_37202.jpg"/><img alt="" src="../upload/image/20180826/20180826215357_53643.jpg"/></p> </span>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (64, 271, 'COPY PAPER', '../upload/image/20181227/20181227113158_83229.jpg', '<p></p><p style="text-indent:20pt;"> <span style="font-size:16px;"><span style=''font-family:"font-size:22px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><strong>COPY PAPER</strong></span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">We have four production lines, which are 5# machine 6# machine 7# machine ,8#machine .</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">And 8# machine is our best production line , this machine stablely manufacture the copy paper products for some</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">larger dealers for the yearly long-term contract .</span></span></span></p> <p style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Out month output are around 8000 Tons/Month :</span></span></p> <table border="1" width="87%"> <tbody> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;" width="50%"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Production Lines ( Machine NO.)</span></span> </div> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;" width="50%"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Output ( Tons/Year )</span></span> </div> </td> </tr> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">8# Machine</span></span> </div> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">4000 Tons</span></span> </div> </td> </tr> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">7# Machine</span></span> </div> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">2000 Tons</span></span> </div> </td> </tr> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">6# Machine</span></span> </div> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1000 Tons</span></span> </div> </td> </tr> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">5# Machine</span></span> </div> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1000 Tons</span></span> </div> </td> </tr> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Total Amount</span></span> </div> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">8000 Tons</span></span> </div> </td> </tr> </tbody> </table> <p align="left" style="text-indent:20pt;"> <span style="font-size:16px;"><span style=''font-family:"";''><br/> <span style=''font-family:"font-size:22px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">In China , we are one of the fewer factories who can offer only copy paper products per month which upto this quantity .</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">We also import part of the raw mateiral(wooden pulp) from overseas like Russia and other area .</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Additionally ,we are also one of the fewer factories who can offer only copy paper products in quality actual 100% wooden pulp best in China .</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Introduction Of Copy Paper</span></span></span></span></p> <p align="left" style="text-indent:20pt;"> <span style="font-size:16px;"><span style=''font-family:"font-size:22px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">The Brand of our Copy Paper are "Phoenix" ,"Orient", "China Tiger" and so forth .</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">The price bases on its quality , There are 3 prices of Copy Paper depending on its brightness in quality or material ,</span></span></span></p> <table border="1" width="88%"> <tbody> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Item: 1</span></span> </div> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Item: 2</span></span> </div> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Item: 3</span></span> </div> </td> </tr> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;" width="34%"> <p align="center" style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Mixed Wooden Pulp</span></span></p> <p align="center" style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">(Non-woodenfree)</span></span></p> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;" width="32%"> <p align="center" style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">100% Wooden Pulp</span></span></p> <p align="center" style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">(Actual woodenfree)</span></span></p> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;" width="34%"> <p align="center" style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">100% Wooden Pulp</span></span></p> <p align="center" style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">(Actual woodenfree)</span></span></p> </td> </tr> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <table border="1" width="100%"> <tbody> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;"> <div align="center"> <span style="color:#E