INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (64, 277, 'LWC paper ( Low-weight coated paper )', '../upload/image/20181227/20181227121049_67702.jpg', '<p></p><table bgcolor="#ffffff" border="0" cellpadding="0" cellspacing="0" class="ke-zeroborder" style="text-align:left;color:#59595B;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;" width="100%"> <tbody> <tr> <td height="25" style="text-align:left;font-family:宋体;font-size:9pt;"> <span style="font-size:22px;"><span style=''font-family:"font-size:24px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><strong>LWC paper ( Low-weight coated paper )</strong></span><br/> <br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">LWC(low-weight coated/light-weight coated ) paper products with GRM is from 48 GRM to 100GRM with outstanding quality . </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Featuring:</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Brightness(ISO) : 84 % ISO. </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Opacity : 90%</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">GlossTS 43% , </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Gloss BS 43%</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Size : In sheet---889*1194,787*1092; </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">In roll --- 760-1050*11000.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Our tech data of this goods following</span></span></span> </td> </tr> <tr> <td height="20" style="text-align:left;font-family:宋体;font-size:9pt;"> </td> </tr> </tbody> </table>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (64, 272, 'Letter(8.5', '../upload/image/20181227/20181227113109_11252.jpg', '<p></p><p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><strong>Letter(8.5"*11")/Legal size (8.5"*14") copy paper</strong></span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''font-family:"font-size:22px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Size : 70 ,75,80GSM 8.5*11,A4,8.5*13,A3,11*17, and foolscap paper sheet is 17 x 13.5inches (432x343 mm) .</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Gram: 80gsm&amp;75gsm&amp;70gsm</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Brightness: 94%~108%</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Wood pulp: 100% wood pulp</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">H.S code :4802560090</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Performance: multi-purpose, can be used for fax machine, laser printing machine and so on; can be printed on both sides without problems; no curl; no jam Place of origin: China Package: 500sheets/ream, 5reams/carton or 10reams/carton,</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Loading : 7800-8000reams/20''container.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Item 80 GSM 8.5X11</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Material wood pulp % </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">CEI Whiteness 148-152 &lt; /TR&gt; </span><br/> <span style="color:#E53333;font-fa