INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (64, 278, '70GSM LWC PAPER FOR MAGAZINE', '../upload/image/20181227/20181227121031_78362.jpg', '<p></p><div style="text-align:left;color:#59595B;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <b><span style="background:white;color:#E53333;font-family:Tahoma;font-size:18px;">70GSM LWC PAPER FOR MAGAZINE</span></b> </div> <div style="text-align:left;color:#59595B;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> </div> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''background:white;color:black;font-family:"font-size:22px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Low-weight coated paper (LWC paper)We are one of the fewer factories who can offer only LWC (low-weight coated ) paper products with GRM is from 48 GRM to 100GRM with outstanding quality . We import the raw mateiral(wooden pulp) from overseas like Russia ,Chile and other areas .</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Plus, we are one of the fewer factories who can offer only LWC paper products in quality actual 100% wooden pulp .</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Our tech data for goods following :</span></span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''background:white;color:black;font-family:"font-size:22px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Brightness(ISO) : 84 % . </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Opacity : 90% Gloss</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">TS 43% , Gloss </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">BS 43%</span></span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''background:white;color:black;font-family:"font-size:22px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Size : In jumbo roll --- width of roll (760MM-1050MM)*Length of roll(11000M);</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">In big sheet --- width*length (889MM*1194MM,787MM*1092MM) and so forth. </span></span></p>', '2026-09-06 20:58:45');